function script:qs_goal_done([string]$id) {
  switch -Exact ($id) {
    'brief' {
      return [bool](q_read 'briefing.txt')
    }
    'alarm' {
      return [bool](-not (q_running 'alarm'))
    }
    'rename' {
      return [bool]((q_count 'telemetry/*.tmp' 0) -and (q_count 'telemetry/*.log' 30))
    }
    'sensors' {
      return [bool]((q_flag 'uplinked') -and (q_exists 'check.ps1'))
    }
    'beacon' {
      return [bool]((q_flag 'transmitted') -and ((q_contains 'beacon.ps1' 'param') -or (q_contains 'beacon.ps1' '$args')))
    }
    'launch' {
      return [bool](q_flag 'launched')
    }
  }
  return $false
}

function script:qs_goal_teach([string]$id) {
  switch -Exact ($id) {
    'brief' {
      q_say 'Five jobs before launch. Read them all first.'
    }
    'alarm' {
      q_say 'Get-Process lists running programs as objects, each with an Id and a Name. Stop-Process -Name alarm stops it (or Stop-Process -Id with its Id).'
    }
    'rename' {
      q_say 'foreach runs the same commands for each item: foreach ($f in Get-ChildItem telemetry\*.tmp) { Rename-Item $f.FullName ($f.BaseName + ".log") }. Each time round, $f is one file object; .BaseName is its name without .tmp.'
    }
    'sensors' {
      q_say 'A script is commands in a .ps1 file. Open the editor with notepad check.ps1 and write: foreach ($f in Get-ChildItem sensors\*.txt) { $temp = [int]((Get-Content $f) -replace "temp=", ""); if ($temp -gt 90) { $f.BaseName } }. Save, then .\check.ps1 | .\uplink.ps1.'
    }
    'beacon' {
      q_say 'A script''s param() block names what it is given: param($Callsign) then "BEACON $Callsign". Run it as .\beacon.ps1 KESTREL and $Callsign is KESTREL. Then pipe it into .\transmitter.ps1.'
    }
    'launch' {
      q_say 'Everything on the checklist is done. Run the launch.'
    }
  }
}

