function script:qs_goal_solution([string]$id) {
  switch -Exact ($id) {
    'brief' {
      return ,@('Get-Content briefing.txt')
    }
    'alarm' {
      return ,@('Get-Process', 'Stop-Process -Name alarm')
    }
    'rename' {
      return ,@('foreach ($f in Get-ChildItem telemetry\*.tmp) { Rename-Item $f.FullName ($f.BaseName + ".log") }')
    }
    'sensors' {
      return ,@('Set-Content check.ps1 @''
      # Outputs every sensor hotter than 90.
      foreach ($f in Get-ChildItem sensors\*.txt) {
        $temp = [int]((Get-Content $f) -replace ''temp='', '''')
        if ($temp -gt 90) { $f.BaseName }
      }
      ''@', '.\check.ps1 | .\uplink.ps1')
    }
    'beacon' {
      return ,@('Set-Content beacon.ps1 ''param($Callsign) "BEACON $Callsign"''', '.\beacon.ps1 KESTREL | .\transmitter.ps1')
    }
    'launch' {
      return ,@('.\launch.ps1')
    }
  }
}

function script:qs_finish_when {
